  (1097728, 322, 72696, 'Tempat makan bernuansa China nilai makanan 1 sampai 9 saya kasi nilai 7 Tempat kurang bersih nilai 6 Kamar mandi kurang nilai 5 Tempat panas nilai 6', 3, NULL, 'Tempat makan bernuansa China nilai makanan 1 sampai 9 saya kasi nilai 7 Tempat kurang bersih nilai 6 Kamar mandi kurang nilai 5 Tempat panas nilai 6', 1),
