  (1098226, 272, 8511, 'Tempat nyaman dan instagramable', 5, NULL, 'Tempat nyaman dan instagramable', 1),
  (1098227, 175, 7244, 'Tempat nya keren,gedhang green tea nya enak,kentang goreng larva nya juga enak,spot foto nya juga enak,bagus nya kalau kesini malam,jadi makin keren suasana nya', 5, NULL, 'Tempat nya keren,gedhang green tea nya enak,kentang goreng larva nya juga enak,spot foto nya juga enak,bagus nya kalau kesini malam,jadi makin keren suasana nya', 1),
  (1098228, 180, 16635, 'agak rame dan berisik karena lagu dan obrolan2 pengunjung, tapi nyaman tempat duduk ada senderan, kopinya 8/10 mantap', 5, NULL, 'agak rame dan berisik karena lagu dan obrolan2 pengunjung, tapi nyaman tempat duduk ada senderan, kopinya 8/10 mantap', 1),
  (1098229, 301, 48973, 'Iseng2 search cafe sekitaran UB buat titik temu sama temen. Akhirnya nyoba kesini. Ada area lantai 1 dan 2. Ada workspace juga soalnya banyak mahasiswa nugas disini. Dan akhirnya setelah kesini sekali, aku mutusin kesana lagi pas lagi main ke malang. Harga menunya basic, pelayanan ramah dan baik. Suasana di dalam, lumayan oke. Ada toilet dan mushola. Tapi mushola dan kamar mandinya agak kotor. Semoga jadi perbaikan kedepannya. Pelayanan cepat, sempat sekali misscom pesanan, sama pelayannya mau diganti, tapi gapapa deh aku gamasalahin juga. Overall bisa jadi opsi kalo lagi ke malang pengen nongkrong dimana.', 4, NULL, 'Iseng2 search cafe sekitaran UB buat titik temu sama temen. Akhirnya nyoba kesini. Ada area lantai 1 dan 2. Ada workspace juga soalnya banyak mahasiswa nugas disini. Dan akhirnya setelah kesini sekali, aku mutusin kesana lagi pas lagi main ke malang. Harga menunya basic, pelayanan ramah dan baik. Suasana di dalam, lumayan oke. Ada toilet dan mushola. Tapi mushola dan kamar mandinya agak kotor. Semoga jadi perbaikan kedepannya. Pelayanan cepat, sempat sekali misscom pesanan, sama pelayannya mau diganti, tapi gapapa deh aku gamasalahin juga. Overall bisa jadi opsi kalo lagi ke malang pengen nongkrong dimana.', 1),
  (1098230, 322, 72895, 'Pot ayam sehat, roti gandum keju/coklat, kopi butter panas adalah menu menu yg menurut saya enak.. … Lainnya', 4, NULL, 'Pot ayam sehat, roti gandum keju/coklat, kopi butter panas adalah menu menu yg menurut saya enak.. … Lainnya', 1),
